selector_to_html = {"a[href=\"install.html#optional-development-containers\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Optional development containers<a class=\"headerlink\" href=\"#optional-development-containers\" title=\"Link to this heading\">#</a></h2><p>The repository ships development container definitions for a CPU image, a\nCUDA image, and variants without JAX that carry QSteed and the compiler plugin\nin one environment. They are the recommended way to reproduce the tutorial and\ninteroperability dependency sets. See the container guide in the repository for\nthe image list and launch commands.</p>", "a[href=\"install.html#verify-the-installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Verify the installation<a class=\"headerlink\" href=\"#verify-the-installation\" title=\"Link to this heading\">#</a></h2>", "a[href=\"requirements.html#execution-targets\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Execution targets<a class=\"headerlink\" href=\"#execution-targets\" title=\"Link to this heading\">#</a></h2><p>CUDA is the only accelerator selected automatically. The FlagOS logical device\nis never chosen implicitly, and no domestic accelerator is certified by\nFlagQuantum alone: the current CUDA-backed reference records the joint\nintegration path, not vendor hardware quality. See\n<a class=\"reference internal\" href=\"../reference/capabilities.html\"><span class=\"std std-doc\">Capabilities</span></a> for the exact scope of every path.</p>", "a[href=\"install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install FlagQuantum<a class=\"headerlink\" href=\"#install-flagquantum\" title=\"Link to this heading\">#</a></h1><p>Read <a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">Requirements</span></a> before proceeding.</p>", "a[href=\"install.html#run-a-first-execution\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Run a first execution<a class=\"headerlink\" href=\"#run-a-first-execution\" title=\"Link to this heading\">#</a></h2><p>The example runs one complete local journey: build a circuit, create an\ninspectable plan, execute that plan on the CPU statevector engine, and compare\nthe result with an analytical reference. The three smallest maintained programs\nare:</p>", "a[href=\"requirements.html#optional-extras\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Optional extras<a class=\"headerlink\" href=\"#optional-extras\" title=\"Link to this heading\">#</a></h2><p>On Python 3.10 the <code class=\"docutils literal notranslate\"><span class=\"pre\">cirq</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">braket</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">cudaq</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">pennylane</span></code>, and <code class=\"docutils literal notranslate\"><span class=\"pre\">quafu</span></code> extras\nare unavailable because the upstream packages require a newer interpreter.</p>", "a[href=\"install.html#migrating-from-the-pre-release-v0-1-api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Migrating from the pre-release v0.1 API<a class=\"headerlink\" href=\"#migrating-from-the-pre-release-v0-1-api\" title=\"Link to this heading\">#</a></h2><p>The v0.1 <code class=\"docutils literal notranslate\"><span class=\"pre\">DistributedQuantumDevice</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">GeneralEncoder</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">InvertibleUnitary</span></code>,\nDTensor interchange helpers, device-oriented gates, and the device-oriented\nmeasurement path are not part of the v0.2 product and have no compatibility\nlayer. Port those programs to <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Circuit</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Module</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.plan</span></code>, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">fq.run</span></code>; see <a class=\"reference internal\" href=\"../user_guide/basic-usage.html\"><span class=\"std std-doc\">Basic Usage</span></a> and\n<a class=\"reference internal\" href=\"../user_guide/training.html\"><span class=\"std std-doc\">Training</span></a>.</p>", "a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">#</a></h1><h2>Software requirements<a class=\"headerlink\" href=\"#software-requirements\" title=\"Link to this heading\">#</a></h2><p>Only PyTorch is required for the local PyTorch path. Every integration is an\noptional extra, so the minimal installation stays small and imports lazily.</p>", "a[href=\"install.html#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Install FlagQuantum<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>The released version from PyPI:</p>", "a[href=\"requirements.html#software-requirements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Software requirements<a class=\"headerlink\" href=\"#software-requirements\" title=\"Link to this heading\">#</a></h2><p>Only PyTorch is required for the local PyTorch path. Every integration is an\noptional extra, so the minimal installation stays small and imports lazily.</p>", "a[href=\"#getting-started\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started<a class=\"headerlink\" href=\"#getting-started\" title=\"Link to this heading\">#</a></h1><p>This section covers the requirements for running FlagQuantum and walks through\ninstallation, verification, and a first execution.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
